1	package net.officefloor.hq.app.rollup;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.time.temporal.ChronoUnit;
7	import java.util.ArrayList;
8	import java.util.Collections;
9	import java.util.LinkedHashMap;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.Objects;
13	import net.officefloor.hq.app.Audit;
14	import net.officefloor.hq.app.claim.Claim;
15	import net.officefloor.hq.app.claim.ClaimRepository;
16	import net.officefloor.hq.app.claim.ClaimStatus;
17	import net.officefloor.hq.app.person.Person;
18	import net.officefloor.hq.app.person.PersonRepository;
19	import net.officefloor.hq.app.rate.Rate;
20	import net.officefloor.hq.app.rate.RateRepository;
21	import net.officefloor.hq.app.settings.DatedSettings;
22	import net.officefloor.hq.app.sheet.Sheet;
23	import net.officefloor.hq.app.sheet.SheetRepository;
24	import org.springframework.stereotype.Service;
25	import org.springframework.transaction.annotation.Propagation;
26	import org.springframework.transaction.annotation.Transactional;
27	
28	/**
29	 * The figures each person on a sheet shows — what they have claimed (their OPEN, PENDING and SETTLED
30	 * claims, leaving out the OPEN and PENDING ones dated within one of their holds, or all of them once their
31	 * retirement date is reached on the sheet's today, that no statement binds)
32	 * and their due-total (the sum of what is due on those claims as each shows it, n/a when none has a figure and no rate of
33	 * their grade is in force on the sheet's today, and at most the sheet's cap in force on its today when it has one) and their
34	 * overdue-total (the sum of what is due on those that are OPEN or PENDING and past their due-by on the
35	 * sheet's today, as each shows it) — and the sheet's totals of them (the due-total and overdue-total
36	 * leave out the single highest and lowest person's figure when three or more people have one; a
37	 * due-total of n/a is no figure). A change that moves
38	 * any of them is followed in the audit by a ROLLUP line per person whose figures moved, then a TOTALS
39	 * line when the sheet's totals moved: take a {@link #snapshot} before the change, and
40	 * {@link #recordSince} it after the change has recorded its own lines.
41	 */
42	@Service
43	public class RollupService {
44	
45	    /** A due-total shown when there is none. */
46	    public static final String NONE = "n/a";
47	
48	    private final PersonRepository people;
49	    private final ClaimRepository claims;
50	    private final RateRepository rates;
51	    private final SheetRepository sheets;
52	    private final DatedSettings dated;
53	    private final Audit audit;
54	
55	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
56	            SheetRepository sheets, DatedSettings dated, Audit audit) {
57	        this.dated = dated;
58	        this.people = people;
59	        this.claims = claims;
60	        this.rates = rates;
61	        this.sheets = sheets;
62	        this.audit = audit;
63	    }
64	
65	    /** A person's figures, as shown. */
66	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
67	    }
68	
69	    /** The sheet's figures at one moment: each person's, by id in the order they were added, and the totals. */
70	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
71	    }
72	
73	    /** The figures the sheet shows now. */
74	    @Transactional(propagation = Propagation.MANDATORY)
75	    public Snapshot snapshot(String sheetId) {
76	        Sheet sheet = sheets.findById(sheetId).orElse(null);
77	        LocalDate today = sheet == null ? null : sheet.getToday();
78	        BigDecimal cap = sheet == null ? null : dated.cap(sheetId);
79	        List<Claim> all = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
80	        Map<Long, Figures> figures = new LinkedHashMap<>();
81	        BigDecimal claimedTotal = zero();
82	        List<BigDecimal> dueFigures = new ArrayList<>();
83	        List<BigDecimal> overdueFigures = new ArrayList<>();
84	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
85	            BigDecimal claimed = zero();
86	            BigDecimal due = zero();
87	            BigDecimal overdue = zero();
88	            boolean any = false;
89	            for (Claim claim : all) {
90	                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person, today)) continue;
91	                claimed = claimed.add(claim.getAmount());
92	                BigDecimal figure = shownOf(claim, person);
93	                if (figure == null) continue;
94	                if (isOverdue(claim, today)) overdue = overdue.add(figure);
95	                due = due.add(figure);
96	                any = true;
97	            }
98	            due = cappedOf(due, cap);
99	            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
100	            claimedTotal = claimedTotal.add(claimed);
101	            overdueFigures.add(overdue);
102	            if (any || rated) dueFigures.add(due);
103	            figures.put(person.getId(), new Figures(person.getName(), text(claimed), any || rated ? text(due) : NONE,
104	                    text(overdue)));
105	        }
106	        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
107	    }
108	
109	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
110	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
111	        BigDecimal sum = figures.stream().reduce(zero(), BigDecimal::add);
112	        if (figures.size() < 3) return sum;
113	        return sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
114	    }
115	
116	    /** Record the ROLLUP and TOTALS lines for the figures that moved since {@code before}. */
117	    @Transactional(propagation = Propagation.MANDATORY)
118	    public void recordSince(String sheetId, String user, Snapshot before) {
119	        Snapshot after = snapshot(sheetId);
120	        after.people().forEach((id, now) -> {
121	            Figures then = before.people().get(id);
122	            if (then != null && then.claimed().equals(now.claimed()) && then.dueTotal().equals(now.dueTotal())
123	                    && then.overdueTotal().equals(now.overdueTotal())) return;
124	            audit.change("ROLLUP", sheetId, user, "person=" + now.name(), "claimed=" + now.claimed(),
125	                    "due-total=" + now.dueTotal(), "overdue-total=" + now.overdueTotal());
126	        });
127	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
128	                || !Objects.equals(before.dueTotal(), after.dueTotal())
129	                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
130	            audit.change("TOTALS", sheetId, user, "claimed-total=" + after.claimedTotal(),
131	                    "due-total=" + after.dueTotal(), "overdue-total=" + after.overdueTotal());
132	        }
133	    }
134	
135	    /** Whether the claim is overdue: OPEN or PENDING, not deferred on the sheet's {@code today}, and due
136	     * by a date before it. */
137	    public static boolean isOverdue(Claim claim, LocalDate today) {
138	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
139	                && !claim.isDeferredOn(today) && claim.getDueBy().isBefore(today);
140	    }
141	
142	    /** A due-total as shown: at most {@code cap}, when there is one. */
143	    public static BigDecimal cappedOf(BigDecimal due, BigDecimal cap) {
144	        return cap == null ? due : due.min(cap);
145	    }
146	
147	    /** Whether the claim counts in the live totals on the sheet's {@code today}: OPEN, PENDING or
148	     * SETTLED, but not an OPEN claim deferred on {@code today}, nor OPEN or PENDING when it is dated
149	     * within one of its person's holds, or its person's retirement date is reached on {@code today}, and
150	     * no statement binds it (a PENDING claim is bound by none while it is). */
151	    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
152	        return countsAs(claim, claim.getStatus(), person, today);
153	    }
154	
155	    /** Whether the claim would count in the live totals on the sheet's {@code today} were its status
156	     * {@code status} (see {@link #countsLive}). */
157	    public static boolean countsAs(Claim claim, ClaimStatus status, Person person, LocalDate today) {
158	        if (!status.counts()) return false;
159	        if (!status.isOpen()) return true;
160	        if (claim.isDeferredOn(today)) return false;
161	        boolean bound = claim.isStated() && status != ClaimStatus.PENDING;
162	        return bound || !(person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
163	    }
164	
165	    /** Whether the claim shows the figure fixed when it was settled at a rate: it is SETTLED, or was
166	     * voided once settled, and has one. */
167	    private static boolean frozen(Claim claim) {
168	        return claim.getSettledDue() != null
169	                && (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID);
170	    }
171	
172	    /** The figure the claim shows and totals now: what was fixed when it was settled at a rate (kept
173	     * once it is voided);
174	     * otherwise, unless it is PENDING (which no statement binds while it is), the figure a statement
175	     * bound it to; otherwise what is due on it at its person's rate.
176	     * Null when it has no figure. */
177	    public BigDecimal figureOf(Claim claim, Person person) {
178	        if (frozen(claim)) return claim.getSettledDue();
179	        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
180	        return dueOf(claim, person);
181	    }
182	
183	    /** What is due on the claim as it shows and totals now: what was fixed when it was settled at a
184	     * rate; otherwise its live due on its figure (see {@link #liveDueOf}); null when it has no figure. */
185	    public BigDecimal shownOf(Claim claim, Person person) {
186	        BigDecimal figure = figureOf(claim, person);
187	        if (frozen(claim)) return figure;
188	        return liveDueOf(claim, figure);
189	    }
190	
191	    /** The live due on the claim whose figure (at its rate, or as a statement bound it) is
192	     * {@code figure}: the greater of the sheet's floor in force on the claim's date and that figure plus
193	     * its late charge (see {@link #lateChargeOf}); a correction has neither floor nor charge. Null when
194	     * {@code figure} is. */
195	    public BigDecimal liveDueOf(Claim claim, BigDecimal figure) {
196	        if (figure == null) return null;
197	        if (claim.isCorrection()) return figure;
198	        return floored(claim, figure.add(lateChargeOf(claim, figure)));
199	    }
200	
201	    /** {@code due}, at least the sheet's floor in force on the claim's date. */
202	    private BigDecimal floored(Claim claim, BigDecimal due) {
203	        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
204	        BigDecimal floor = sheet == null ? zero() : dated.floorOn(sheet.getId(), claim.getDate());
205	        return due.max(floor);
206	    }
207	
208	    /** The late charge on an OPEN or PENDING claim whose figure is {@code figure}: for every full 30 days the claim is overdue (past its due-by, fixed when it was added, on
209	     * the sheet's today), the sheet's late percent in force on that boundary date (the due-by plus 30, 60,
210	     * 90 ... days) of that figure, rounded to two decimals as the claim rounds, the charges added up (a boundary whose percent is 0.00 adds nothing) (see {@link #roundingOf}); 0.00 on a claim not OPEN or
211	     * PENDING, or not overdue (a deferred claim is not), and on a correction. A statement never binds it: it follows the sheet's today until the claim is settled. */
212	    public BigDecimal lateChargeOf(Claim claim, BigDecimal figure) {
213	        if (!claim.getStatus().isOpen()) return zero();
214	        return overdueChargeOf(claim, figure);
215	    }
216	
217	    /** What would be due on the claim now were it an OPEN claim bound by no statement: its due at its
218	     * person's rate (see {@link #dueOf}) plus the late charge it would have then, at least the sheet's
219	     * floor in force on its date (a correction has neither); null when it would have no figure. */
220	    public BigDecimal openShownOf(Claim claim, Person person) {
221	        BigDecimal figure = dueOf(claim, person);
222	        if (figure == null || claim.isCorrection()) return figure;
223	        return floored(claim, figure.add(overdueChargeOf(claim, figure)));
224	    }
225	
226	    /** The late charge on a claim whose figure is {@code figure}, whatever its status (see {@link #lateChargeOf}). */
227	    private BigDecimal overdueChargeOf(Claim claim, BigDecimal figure) {
228	        if (claim.isCorrection()) return zero();
229	        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
230	        if (sheet == null || claim.isDeferredOn(sheet.getToday())) return zero();
231	        long periods = Math.max(0, ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday())) / 30;
232	        RoundingMode rounding = roundingOf(claim, sheet);
233	        BigDecimal charge = zero();
234	        for (long k = 1; k <= periods; k++) {
235	            BigDecimal pct = dated.latePctOn(sheet.getId(), claim.getDueBy().plusDays(30 * k));
236	            if (pct.signum() == 0) continue;
237	            charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
238	        }
239	        return charge;
240	    }
241	
242	    /** What is due on the claim at its person's rate in force on the claim's date: amount times pct,
243	     * divided by 100, rounded to two decimals as the claim rounds (see {@link #roundingOf}) — the rate
244	     * figure alone, before any late charge or floor (see {@link #liveDueOf}); null when no
245	     * rate of the grade in force for them on the claim's date applies then. */
246	    public BigDecimal dueOf(Claim claim, Person person) {
247	        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
248	        RoundingMode rounding = roundingOf(claim, sheet);
249	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
250	                .map(Rate::getPct)
251	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
252	                .orElse(null);
253	    }
254	
255	    /** How the claim's live figures round: half up when it is dated before the sheet's policy date in
256	     * force, half to even when on or after it. A correction rounds by the date of the claim it corrects. */
257	    public RoundingMode roundingOf(Claim claim, Sheet sheet) {
258	        if (sheet == null) return RoundingMode.HALF_EVEN;
259	        LocalDate dated = claim.getDate();
260	        if (claim.isCorrection() && claim.getCorrects() != null) {
261	            dated = claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
262	                    .map(Claim::getDate).orElse(dated);
263	        }
264	        return dated.isBefore(sheet.policyDateInForce()) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
265	    }
266	
267	    private static BigDecimal zero() {
268	        return BigDecimal.ZERO.setScale(2);
269	    }
270	
271	    private static String text(BigDecimal value) {
272	        return value.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
273	    }
274	}
