package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's rate for a grade: a percent (0.00 or more, two decimals), in force from its from-date on
 * (from the beginning of time when it has none) through its to-date (with no end when it has none). */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    /** The date the rate applies from; null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** The last date the rate applies on; null when it applies on with no end. */
    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The sheet's rates, by grade, then by from-date (one with none first). */
    @Query("SELECT r FROM Rate r WHERE r.sheetId = :sheetId ORDER BY r.grade ASC, r.from ASC NULLS FIRST")
    List<Rate> findBySheetIdOrderByGradeAndFrom(String sheetId);

    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    @Query("SELECT r FROM Rate r WHERE r.sheetId = :sheetId AND r.grade = :grade AND r.from IS NULL")
    Optional<Rate> findUndated(String sheetId, String grade);

    Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from);

    /** The grade's rate in force on {@code date}: the one with the latest from-date on or before it, or
     * the one with no from-date when none has; empty when no rate applies yet, or when that rate's
     * to-date is before {@code date} (an earlier rate does not apply again). */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> r.getTo() == null || !r.getTo().isBefore(date));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates each grade has on each sheet, each from its from-date on (or from the beginning of time)
 * through its to-date (or with no end).
 * Setting a grade's rate for a from-date it already has a rate for replaces that rate. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public RateService(RateRepository rates, SheetRepository sheets, Audit audit, RollupService rollup) {
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The sheet's rates, by grade, then by from-date. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAndFrom(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        if (from != null && to != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = (from == null ? rates.findUndated(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from)).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, pct));
        } else {
            rate.setPct(pct);
            rate.setTo(to);
            rates.flush();
        }
        List<String> fields = new ArrayList<>(List.of("grade=" + grade,
                "rate=" + rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()));
        if (from != null) fields.add("from=" + from);
        if (to != null) fields.add("to=" + to);
        audit.change("RATE_SET", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return rate;
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The values in force of a sheet's dated settings: on a date, the value recorded with the latest
 * from-date on or before it, and before every from-date the sheet's starting value (floor 1.00, late
 * percent 0.00, terms 14 days; no clerk limit, no cap, no proof threshold and no grade's own terms). A claim's floor, late
 * percent, terms and proof threshold are those in force on its date; the clerk limit and the cap those on the sheet's
 * today. */
@Service
public class DatedSettings {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";

    public static final BigDecimal FLOOR_START = new BigDecimal("1.00");
    public static final BigDecimal LATE_PCT_START = new BigDecimal("0.00");
    public static final int TERMS_START = 14;

    private final SheetSettingRepository settings;
    private final SheetRepository sheets;

    public DatedSettings(SheetSettingRepository settings, SheetRepository sheets) {
        this.settings = settings;
        this.sheets = sheets;
    }

    /** The key a grade's own terms are kept under. */
    public static String gradeTermsKey(String grade) {
        return TERMS + "-" + grade;
    }

    /** Every value recorded for the key, oldest from-date first. */
    @Transactional(readOnly = true)
    public List<SheetSetting> history(String sheetId, String key) {
        return settings.findBySheetIdAndKeyOrderByFromAsc(sheetId, key);
    }

    @Transactional(readOnly = true)
    public BigDecimal floorOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, FLOOR, date).map(BigDecimal::new).orElse(FLOOR_START);
    }

    @Transactional(readOnly = true)
    public BigDecimal latePctOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, LATE_PCT, date).map(BigDecimal::new).orElse(LATE_PCT_START);
    }

    /** The sheet's own terms in force on the date, in days. */
    @Transactional(readOnly = true)
    public int termsOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, TERMS, date).map(Integer::valueOf).orElse(TERMS_START);
    }

    /** The grade's own terms in force on the date, in days; null when it uses the sheet's terms then. */
    @Transactional(readOnly = true)
    public Integer gradeTermsOn(String sheetId, String grade, LocalDate date) {
        return valueOn(sheetId, gradeTermsKey(grade), date).map(Integer::valueOf).orElse(null);
    }

    /** The terms a claim dated {@code date} of a person of {@code grade} is due by: the grade's own in
     * force then, or else the sheet's in force then. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(sheetId, grade, date);
        return own != null ? own : termsOn(sheetId, date);
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return valueOn(sheetId, CLERK_LIMIT, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The cap in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return valueOn(sheetId, CAP, today(sheetId)).map(BigDecimal::new).orElse(null);
    }

    /** The proof threshold in force on the date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdOn(String sheetId, LocalDate date) {
        return valueOn(sheetId, PROOF_THRESHOLD, date).map(BigDecimal::new).orElse(null);
    }

    /** The value of the key in force on the date; empty when none is recorded then, or the one
     * recorded is "none". */
    private Optional<String> valueOn(String sheetId, String key, LocalDate date) {
        return settings.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(sheetId, key, date)
                .map(SheetSetting::getValue);
    }

    private LocalDate today(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
    }
}
package net.officefloor.hq.app.settings;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A value of one of a sheet's dated settings, recorded from a date; a null value records "none" from
 * then (no clerk limit, no cap, or a grade using the sheet's terms). */
@Entity
@Table(name = "sheet_setting")
public class SheetSetting {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "setting_value")
    private String value;

    protected SheetSetting() {
    }

    public SheetSetting(String sheetId, String key, LocalDate from, String value) {
        this.sheetId = sheetId;
        this.key = key;
        this.from = from;
        this.value = value;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    public String getValue() {
        return value;
    }

    public void setValue(String value) {
        this.value = value;
    }
}
